dense_results = {"chunk_1": 0.92, "chunk_2": 0.85, "chunk_3": 0.40}
sparse_results = {"chunk_1": 0.20, "chunk_2": 0.95, "chunk_3": 0.88}

def combine_scores(dense_results, sparse_results, dense_weight=0.5, sparse_weight=0.5):
    # weighted linear combination of dense and sparse scores
    all_chunks = set(dense_results) | set(sparse_results)
    combined = {}
    for chunk in all_chunks:
        d_score = dense_results.get(chunk, 0)
        s_score = sparse_results.get(chunk, 0)
        combined[chunk] = dense_weight * d_score + sparse_weight * s_score
    return combined

balanced = combine_scores(dense_results, sparse_results, dense_weight=0.5, sparse_weight=0.5)
sparse_favored = combine_scores(dense_results, sparse_results, dense_weight=0.2, sparse_weight=0.8)

print("Balanced hybrid scores:")
for chunk, score in sorted(balanced.items(), key=lambda x: -x[1]):
    print(f"  {chunk}: {score:.3f}")

print("\nSparse favored hybrid scores:")
for chunk, score in sorted(sparse_favored.items(), key=lambda x: -x[1]):
    print(f"  {chunk}: {score:.3f}")
